-- NOVA INDEPENDENT EN-FA COURSE V2
-- SERIES 2
-- Stage: en-fa-a1-series-0002
-- Schema: v9.0; idempotent chapter import; no schema changes.
SET NAMES utf8mb4;
DELIMITER $$
DROP PROCEDURE IF EXISTS import_nova_en_series_002$$
CREATE PROCEDURE import_nova_en_series_002()
BEGIN
  DECLARE v_count INT DEFAULT 0;
  DECLARE v_course BIGINT UNSIGNED;
  DECLARE v_level BIGINT UNSIGNED;
  DECLARE v_module BIGINT UNSIGNED;
  DECLARE v_chapter BIGINT UNSIGNED;
  DECLARE v_c_arman BIGINT UNSIGNED;
  DECLARE v_c_maya BIGINT UNSIGNED;
  DECLARE v_c_nora BIGINT UNSIGNED;
  DECLARE v_c_daniel BIGINT UNSIGNED;
  DECLARE v_l_1 BIGINT UNSIGNED;
  DECLARE v_l_2 BIGINT UNSIGNED;
  DECLARE v_l_3 BIGINT UNSIGNED;
  DECLARE v_l_4 BIGINT UNSIGNED;
  DECLARE v_t_1 BIGINT UNSIGNED;
  DECLARE v_t_2 BIGINT UNSIGNED;
  DECLARE v_t_3 BIGINT UNSIGNED;
  DECLARE v_t_4 BIGINT UNSIGNED;
  DECLARE v_t_5 BIGINT UNSIGNED;
  DECLARE v_t_6 BIGINT UNSIGNED;
  DECLARE v_t_7 BIGINT UNSIGNED;
  DECLARE v_t_8 BIGINT UNSIGNED;
