  DECLARE v_t_23 BIGINT UNSIGNED;
  DECLARE v_t_24 BIGINT UNSIGNED;
  DECLARE v_t_25 BIGINT UNSIGNED;
  DECLARE v_t_26 BIGINT UNSIGNED;
  DECLARE v_t_27 BIGINT UNSIGNED;
  DECLARE v_t_28 BIGINT UNSIGNED;
  DECLARE v_t_29 BIGINT UNSIGNED;
  DECLARE v_t_30 BIGINT UNSIGNED;
  DECLARE v_t_31 BIGINT UNSIGNED;
  DECLARE v_t_32 BIGINT UNSIGNED;
  DECLARE v_t_33 BIGINT UNSIGNED;
  DECLARE v_t_34 BIGINT UNSIGNED;
  DECLARE v_t_35 BIGINT UNSIGNED;
  DECLARE v_t_36 BIGINT UNSIGNED;
  DECLARE v_t_37 BIGINT UNSIGNED;
  DECLARE v_t_38 BIGINT UNSIGNED;
  DECLARE v_w_001 BIGINT UNSIGNED;
  DECLARE v_w_002 BIGINT UNSIGNED;
  DECLARE v_w_003 BIGINT UNSIGNED;
  DECLARE v_w_004 BIGINT UNSIGNED;
  DECLARE v_w_005 BIGINT UNSIGNED;
  DECLARE v_w_006 BIGINT UNSIGNED;
  DECLARE v_w_007 BIGINT UNSIGNED;
  DECLARE v_w_008 BIGINT UNSIGNED;
  DECLARE v_w_009 BIGINT UNSIGNED;
  DECLARE v_w_010 BIGINT UNSIGNED;
  DECLARE v_w_011 BIGINT UNSIGNED;
  DECLARE v_w_012 BIGINT UNSIGNED;
  DECLARE v_w_013 BIGINT UNSIGNED;
  DECLARE v_w_014 BIGINT UNSIGNED;
  DECLARE v_w_015 BIGINT UNSIGNED;
  DECLARE v_w_016 BIGINT UNSIGNED;
  DECLARE v_w_017 BIGINT UNSIGNED;
  DECLARE v_w_018 BIGINT UNSIGNED;
  DECLARE v_w_019 BIGINT UNSIGNED;
  DECLARE v_w_020 BIGINT UNSIGNED;
  DECLARE v_w_021 BIGINT UNSIGNED;
  DECLARE v_w_022 BIGINT UNSIGNED;
  DECLARE v_w_023 BIGINT UNSIGNED;
  DECLARE v_w_024 BIGINT UNSIGNED;
  DECLARE v_w_025 BIGINT UNSIGNED;
  DECLARE v_w_026 BIGINT UNSIGNED;
  DECLARE v_w_027 BIGINT UNSIGNED;
  DECLARE v_w_028 BIGINT UNSIGNED;
  DECLARE v_w_029 BIGINT UNSIGNED;
  DECLARE v_w_030 BIGINT UNSIGNED;
  DECLARE v_w_031 BIGINT UNSIGNED;
  DECLARE v_w_032 BIGINT UNSIGNED;
  DECLARE v_w_033 BIGINT UNSIGNED;
  DECLARE v_w_034 BIGINT UNSIGNED;
  DECLARE v_w_035 BIGINT UNSIGNED;
  DECLARE v_w_036 BIGINT UNSIGNED;
  DECLARE v_w_037 BIGINT UNSIGNED;
  DECLARE v_w_038 BIGINT UNSIGNED;
  DECLARE v_w_039 BIGINT UNSIGNED;
  DECLARE v_w_040 BIGINT UNSIGNED;
  DECLARE v_w_041 BIGINT UNSIGNED;
  DECLARE v_w_042 BIGINT UNSIGNED;
  DECLARE v_w_043 BIGINT UNSIGNED;
  DECLARE v_w_044 BIGINT UNSIGNED;
  DECLARE v_w_045 BIGINT UNSIGNED;
  DECLARE v_w_046 BIGINT UNSIGNED;
  DECLARE v_w_047 BIGINT UNSIGNED;
  DECLARE v_w_048 BIGINT UNSIGNED;
  DECLARE v_w_049 BIGINT UNSIGNED;
  DECLARE v_w_050 BIGINT UNSIGNED;
  DECLARE v_w_051 BIGINT UNSIGNED;
  DECLARE v_w_052 BIGINT UNSIGNED;
  DECLARE v_w_053 BIGINT UNSIGNED;
  DECLARE v_w_054 BIGINT UNSIGNED;
  DECLARE v_w_055 BIGINT UNSIGNED;
  DECLARE v_w_056 BIGINT UNSIGNED;
  DECLARE v_w_057 BIGINT UNSIGNED;
  DECLARE v_w_058 BIGINT UNSIGNED;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  START TRANSACTION;
  SELECT COUNT(*),MIN(id) INTO v_count,v_course FROM courses WHERE learning_language='en' AND base_language='fa';
  IF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='en-fa course must exist before Series 2'; END IF;
  SELECT COUNT(*),MIN(id) INTO v_count,v_level FROM levels WHERE course_id=v_course AND cefr_level='A1';
  IF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='A1 level identity is not unique'; END IF;
  SELECT COUNT(*),MIN(id) INTO v_count,v_module FROM modules WHERE level_id=v_level AND sort_order=1;
  IF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='A1 module identity is not unique'; END IF;
  SELECT COUNT(*),MIN(id) INTO v_count,v_c_arman FROM characters WHERE course_id=v_course AND name='Arman';
  IF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Arman identity is not unique'; END IF;
  SELECT COUNT(*),MIN(id) INTO v_count,v_c_maya FROM characters WHERE course_id=v_course AND name='Maya';
  IF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Maya identity is not unique'; END IF;
  SELECT COUNT(*),MIN(id) INTO v_count,v_c_nora FROM characters WHERE course_id=v_course AND name='Nora';
  IF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Nora identity is not unique'; END IF;
  SELECT COUNT(*),MIN(id) INTO v_count,v_c_daniel FROM characters WHERE course_id=v_course AND name='Daniel';
  IF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Daniel identity is not unique'; END IF;
  IF (SELECT COUNT(*) FROM chapters WHERE module_id=v_module AND sort_order=1)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Series 1 prerequisite is missing'; END IF;
  SELECT COUNT(*),MIN(id) INTO v_count,v_chapter FROM chapters WHERE module_id=v_module AND sort_order=2;
  IF v_count=0 THEN
    SELECT id INTO v_w_001 FROM words WHERE course_id=v_course AND lemma='hello' AND part_of_speech='interjection';
    SELECT id INTO v_w_002 FROM words WHERE course_id=v_course AND lemma='i' AND part_of_speech='pronoun';
    SELECT id INTO v_w_003 FROM words WHERE course_id=v_course AND lemma='be' AND part_of_speech='verb';
    SELECT id INTO v_w_005 FROM words WHERE course_id=v_course AND lemma='arman' AND part_of_speech='noun';
    SELECT id INTO v_w_007 FROM words WHERE course_id=v_course AND lemma='your' AND part_of_speech='determiner';
    SELECT id INTO v_w_009 FROM words WHERE course_id=v_course AND lemma='name' AND part_of_speech='noun';
    SELECT id INTO v_w_010 FROM words WHERE course_id=v_course AND lemma='my' AND part_of_speech='determiner';
    SELECT id INTO v_w_013 FROM words WHERE course_id=v_course AND lemma='please' AND part_of_speech='interjection';
    SELECT id INTO v_w_015 FROM words WHERE course_id=v_course AND lemma='a' AND part_of_speech='determiner';
    SELECT id INTO v_w_017 FROM words WHERE course_id=v_course AND lemma='yes' AND part_of_speech='interjection';
    SELECT id INTO v_w_019 FROM words WHERE course_id=v_course AND lemma='iran' AND part_of_speech='noun';
    SELECT id INTO v_w_020 FROM words WHERE course_id=v_course AND lemma='where' AND part_of_speech='adverb';
    SELECT id INTO v_w_021 FROM words WHERE course_id=v_course AND lemma='do' AND part_of_speech='function_word';
    SELECT id INTO v_w_022 FROM words WHERE course_id=v_course AND lemma='you' AND part_of_speech='pronoun';
    SELECT id INTO v_w_023 FROM words WHERE course_id=v_course AND lemma='live' AND part_of_speech='verb';
    SELECT id INTO v_w_024 FROM words WHERE course_id=v_course AND lemma='now' AND part_of_speech='adverb';
    SELECT id INTO v_w_025 FROM words WHERE course_id=v_course AND lemma='in' AND part_of_speech='adverb';
    SELECT id INTO v_w_026 FROM words WHERE course_id=v_course AND lemma='london' AND part_of_speech='noun';
    SELECT id INTO v_w_028 FROM words WHERE course_id=v_course AND lemma='on' AND part_of_speech='adverb';
    SELECT id INTO v_w_031 FROM words WHERE course_id=v_course AND lemma='great' AND part_of_speech='adjective';
    SELECT id INTO v_w_032 FROM words WHERE course_id=v_course AND lemma='new' AND part_of_speech='adjective';
    SELECT id INTO v_w_034 FROM words WHERE course_id=v_course AND lemma='this' AND part_of_speech='pronoun';
    SELECT id INTO v_w_035 FROM words WHERE course_id=v_course AND lemma='nice' AND part_of_speech='adjective';
    SELECT id INTO v_w_036 FROM words WHERE course_id=v_course AND lemma='to' AND part_of_speech='adverb';
    SELECT id INTO v_w_038 FROM words WHERE course_id=v_course AND lemma='with' AND part_of_speech='adverb';
    SELECT id INTO v_w_043 FROM words WHERE course_id=v_course AND lemma='the' AND part_of_speech='determiner';
    SELECT id INTO v_w_045 FROM words WHERE course_id=v_course AND lemma='how' AND part_of_speech='adverb';
    SELECT id INTO v_w_048 FROM words WHERE course_id=v_course AND lemma='correct' AND part_of_speech='adjective';
    SELECT id INTO v_w_049 FROM words WHERE course_id=v_course AND lemma='welcome' AND part_of_speech='interjection';
    SELECT id INTO v_w_050 FROM words WHERE course_id=v_course AND lemma='from' AND part_of_speech='adverb';
    SELECT id INTO v_w_052 FROM words WHERE course_id=v_course AND lemma='here' AND part_of_speech='adverb';
    SELECT id INTO v_w_053 FROM words WHERE course_id=v_course AND lemma='no' AND part_of_speech='interjection';
    SELECT id INTO v_w_055 FROM words WHERE course_id=v_course AND lemma='maya' AND part_of_speech='noun';
    SELECT id INTO v_w_058 FROM words WHERE course_id=v_course AND lemma='ready' AND part_of_speech='adjective';
  ELSEIF v_count=1 THEN
    SELECT id INTO v_chapter FROM chapters WHERE module_id=v_module AND sort_order=2;
    IF (SELECT COUNT(*) FROM lessons WHERE chapter_id=v_chapter)<>4 OR (SELECT COUNT(*) FROM turns t JOIN lessons l ON l.id=t.lesson_id WHERE l.chapter_id=v_chapter)<>38 OR (SELECT COUNT(*) FROM activities a JOIN lessons l ON l.id=a.lesson_id WHERE l.chapter_id=v_chapter)<>72 OR JSON_UNQUOTE(JSON_EXTRACT((SELECT metadata FROM chapters WHERE id=v_chapter),'$.stageId'))<>'en-fa-a1-series-0002' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Existing chapter does not match validated stage'; END IF;
  ELSE SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Chapter identity is not unique'; END IF;
  IF (SELECT COUNT(*) FROM lessons WHERE chapter_id=v_chapter)<>4 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Chapter must contain exactly four lessons'; END IF;
  IF EXISTS (SELECT 1 FROM lessons l LEFT JOIN turns t ON t.lesson_id=l.id WHERE l.chapter_id=v_chapter GROUP BY l.id HAVING COUNT(t.id)<8 OR COUNT(t.id)>14) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Turn quota failed'; END IF;
  IF EXISTS (SELECT 1 FROM lessons l LEFT JOIN activities a ON a.lesson_id=l.id WHERE l.chapter_id=v_chapter GROUP BY l.id HAVING COUNT(a.id)<12 OR COUNT(a.id)>18) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Activity quota failed'; END IF;
  COMMIT;
END$$
CALL import_nova_en_series_002()$$
DROP PROCEDURE IF EXISTS import_nova_en_series_002$$
DELIMITER ;
